import type { AgentAdapterId, AgentDefinition } from '@vahu-ef/schemas';

/**
 * An adapter renders canonical definitions into one provider's file. It states
 * what it can and cannot express, so a caller never assumes more support than
 * the adapter provides.
 */
export interface AgentAdapter {
  id: AgentAdapterId;
  name: string;
  outputPath: string;
  supported: readonly string[];
  unsupported: readonly string[];
  render(definitions: readonly AgentDefinition[]): string;
}

const HEADER =
  '<!-- Generated by VAHU (generic adapter). Edit the canonical definitions, not this file. -->';

/**
 * Renders provider-neutral Markdown. Output is deterministic: definitions are
 * ordered by identifier and no timestamp or environment value is included.
 */
export function renderGeneric(definitions: readonly AgentDefinition[]): string {
  const ordered = [...definitions].sort((left, right) => left.id.localeCompare(right.id));
  const lines = [HEADER, '', '# VAHU agent instructions', ''];

  if (ordered.length === 0) {
    lines.push('No agent definitions were selected.');
    return `${lines.join('\n')}\n`;
  }

  lines.push(
    `Generated from ${ordered.length} canonical definition(s): ${ordered.map((item) => item.id).join(', ')}.`,
  );

  for (const definition of ordered) {
    lines.push('', `## ${definition.name} (${definition.id})`, '', definition.description);

    if (definition.instructions.length > 0) {
      lines.push('', '### Instructions');
      lines.push(...definition.instructions.map((instruction) => `- ${instruction}`));
    }

    if (definition.rules.length > 0) {
      lines.push('', '### Rules');
      for (const rule of definition.rules) {
        const scope = rule.path ? `${rule.scope}: ${rule.path}` : rule.scope;
        lines.push(`- **${rule.id}** (${scope}): ${rule.text}`);
      }
    }

    if (definition.skills.length > 0) {
      lines.push('', '### Skills');
      for (const skill of definition.skills) {
        lines.push(
          `- **${skill.name}**: ${skill.description}${skill.path ? ` (${skill.path})` : ''}`,
        );
      }
    }

    if (definition.commands.length > 0) {
      lines.push('', '### Commands');
      for (const command of definition.commands) {
        lines.push(
          `- **${command.name}**: ${command.description}${command.run ? ` — \`${command.run}\`` : ''}`,
        );
      }
    }

    if (definition.workflows.length > 0) {
      lines.push('', '### Workflows');
      for (const workflow of definition.workflows) {
        lines.push('', `#### ${workflow.name}`);
        lines.push(...workflow.steps.map((step, index) => `${index + 1}. ${step}`));
      }
    }

    if (definition.tools.length > 0) {
      lines.push('', '### Tools');
      for (const tool of definition.tools) {
        const requirements = [
          tool.required ? 'required' : 'optional',
          `approval: ${tool.approval}`,
        ];
        lines.push(`- **${tool.name}** (${requirements.join('; ')})`);
      }
    }

    if (definition.context.length > 0) {
      lines.push('', '### Context');
      for (const reference of definition.context) {
        lines.push(
          `- \`${reference.path}\`${reference.description ? `: ${reference.description}` : ''}`,
        );
      }
    }

    if (definition.approvals.length > 0) {
      lines.push('', '### Approvals');
      lines.push(...definition.approvals.map((approval) => `- ${approval}`));
    }
  }

  return `${lines.join('\n')}\n`;
}

export const genericAdapter: AgentAdapter = {
  id: 'generic',
  name: 'Generic Markdown instructions',
  outputPath: 'AGENTS.md',
  supported: [
    'instructions',
    'rules',
    'skills',
    'commands',
    'workflows',
    'tools',
    'context',
    'approvals',
  ],
  unsupported: [],
  render: renderGeneric,
};
